var rowY = [438, 306, 174, 42];
function E(v, tag) { return { v: v, tag: tag || null }; }
var levelsData = [
  [ [E(5)],[E(2,'a')],[E(4)],[E(7)],[E(1)],[E(3)],[E(2,'b')],[E(6)] ],
  [ [E(2,'a'),E(5)],[E(4),E(7)],[E(1),E(3)],[E(2,'b'),E(6)] ],
