var DIM_LV = 0.32, DIM_AR = 0.12;

var labelsG  = draw.group();
var tierGroups = [draw.group(), draw.group(), draw.group()];
var levelGroups = [draw.group(), draw.group(), draw.group(), draw.group()];
var overlayG = draw.group().attr('pointer-events','none');

/* ── build nodes (geometry + cells) ─────────────────────────────── */
var levels = [[],[],[],[]];
var i, j, k;
for (i = 0; i < 8; i++) {
  levels[0].push({ level:0, idx:i, els:levelsData[0][i], x:X0+i*DX, y:rowY[0], w:CW, h:RH });
}
for (i = 1; i <= 3; i++) {
  for (j = 0; j < levelsData[i].length; j++) {
    var c0 = levels[i-1][2*j], c1 = levels[i-1][2*j+1];
    var w = levelsData[i][j].length * CW;
    var cx = ( (c0.x + c0.w/2) + (c1.x + c1.w/2) ) / 2;
    levels[i].push({ level:i, idx:j, els:levelsData[i][j], x:cx-w/2, y:rowY[i], w:w, h:RH });
  }
}
function nodeVals(nd){ return nd.els.map(function(e){return e.v;}).join(' '); }

function drawNode(nd) {
  var g = levelGroups[nd.level].group();
  nd.group = g; nd.cells = [];
  for (k = 0; k < nd.els.length; k++) {
    var cx0 = nd.x + k*CW;
    var cell = {
      x: cx0, y: nd.y, cx: cx0 + CW/2,
      bg:   g.rect(CW, RH).move(cx0, nd.y).fill('#e7e7e7'),
      text: g.text(String(nd.els[k].v)).font({family:SERIF,size:23,anchor:'middle'}).fill('#111').attr({x:cx0+CW/2, y:nd.y+RH/2+8}),
      tag:  g.text(nd.els[k].tag || '').font({family:SERIF,size:13,style:'italic',anchor:'middle'}).fill(TAGC[nd.els[k].tag]||'#000').opacity(0).attr({x:cx0+CW/2+15, y:nd.y+RH-6})
    };
    nd.cells.push(cell);
  }
  g.rect(nd.els.length*CW, RH).move(nd.x, nd.y).fill('none').stroke({color:'#111',width:1.4});
  for (k = 1; k < nd.els.length; k++) g.line(nd.x+k*CW, nd.y, nd.x+k*CW, nd.y+RH).stroke({color:'#111',width:1});
  g.css('cursor','pointer');
  g.on('mousemove', function(ev){ showTooltip('sorted run [ ' + nodeVals(nd) + ' ]', ev); });
  g.on('mouseleave', function(){ hideTooltip(); });
  g.on('click', function(){
    var body;
    if (nd.level === 0) {
      body = 'A single element is trivially a sorted run. Merge sort starts here: pair up neighbors and merge them into sorted runs of length 2.';
    } else {
