/* ── code editor: samples ───────────────────────────────────────── */
var SAMPLE = 'while (!isEmpty("left") && !isEmpty("right")) {\n  if (lessOrEqual(front("left"), front("right"))) {\n    take("left");      // ties go to the LEFT run\n  } else {\n    take("right");\n  }\n}\nwhile (!isEmpty("left")) take("left");   // drain leftovers\nwhile (!isEmpty("right")) take("right");';
var BUGGY = 'while (!isEmpty("left") && !isEmpty("right")) {\n  if (front("left") < front("right")) {   // BUG: strict < sends ties to the right run, destroying stability\n    take("left");\n  } else {\n    take("right");\n  }\n}\nwhile (!isEmpty("left")) take("left");\nwhile (!isEmpty("right")) take("right");';
var STARTER = '// merge(left, right): combine two sorted runs into one sorted run.\n// Primitives (each call adds a replay frame):\n//   front(side)        -> front value of "left"/"right" (undefined if empty)\n//   isEmpty(side)      -> true when that run is used up\n//   lessOrEqual(a, b)  -> a <= b ; choosing <= over < decides ties\n//   take(side)         -> move that run\'s front value to the output\n//   note(text)         -> mark the current frame\n\n';
