/* ── run parsing + tree lookup ──────────────────────────────────── */
function parseRuns(str) {
  var parts = String(str).split('|');
  if (parts.length !== 2) throw new Error('expected two runs separated by |');
  function parseSide(s) {
    var toks = s.split(',').map(function(t){return t.trim();}).filter(function(t){return t.length;});
    if (!toks.length) throw new Error('a run is empty');
    var nums = toks.map(Number);
    if (nums.some(function(n){ return !isFinite(n); })) throw new Error('runs must be numbers separated by commas');
    if (nums.length > 8) throw new Error('runs can have at most 8 values');
    return nums;
  }
  return { left: parseSide(parts[0]), right: parseSide(parts[1]) };
}
function eqArr(a, b) {
  if (a.length !== b.length) return false;
  for (var q = 0; q < a.length; q++) if (a[q] !== b[q]) return false;
  return true;
}
function findMerge(lv, rv) {
  for (var li = 3; li >= 1; li--) {
    for (var q = 0; q < levels[li].length; q++) {
      var c0 = levels[li-1][2*q], c1 = levels[li-1][2*q+1];
      if (eqArr(c0.els.map(function(e){return e.v;}), lv) && eqArr(c1.els.map(function(e){return e.v;}), rv))
        return { tier: li-1, parent: levels[li][q], left: c0, right: c1 };
    }
  }
  return null;
}

/* ── worker: run student code with framing API ──────────────────── */
var workerFn = function () {
  var L = [], R = [], out = [], li = 0, ri = 0, frames = [], ops = 0, t0 = 0;
  var MAXOPS = 3000, MAXFRAMES = 600, LIMIT = 1500;
  function tick() {
    if (Date.now() - t0 > LIMIT) throw new Error('time limit exceeded — check for an infinite loop');
    if (++ops > MAXOPS) throw new Error('operation limit exceeded');
  }
  function copyOut() { return out.map(function(e){ return {v:e.v, tag:e.tag, uid:e.uid}; }); }
  function snap(kind, indices, msg) {
    frames.push({kind:kind, indices:indices, message:msg, state:{li:li, ri:ri, out:copyOut()}});
    if (frames.length > MAXFRAMES) throw new Error('frame limit exceeded');
  }
  function arrOf(side) {
    if (side === 'left') return L; if (side === 'right') return R;
    throw new Error('side must be "left" or "right", got ' + JSON.stringify(side));
  }
  function fmt(e) { return e ? String(e.v) : 'undefined'; }
  function front(side) {
    tick(); var A = arrOf(side); var idx = (side === 'left') ? li : ri; var e = A[idx];
    snap('front', [{side:side, index:idx}], 'front("' + side + '") -> ' + fmt(e) + (e ? '' : ' (run is empty)'));
    return e ? e.v : undefined;
  }
  function isEmpty(side) {
    tick(); var A = arrOf(side); var idx = (side === 'left') ? li : ri; var empty = idx >= A.length;
    snap('isempty', [{side:side, index:Math.min(idx, A.length-1)}], 'isEmpty("' + side + '") -> ' + empty);
    return empty;
  }
  function lessOrEqual(a, b) {
    tick(); var r = (a <= b);
    snap('compare', [{side:'left', index:li}, {side:'right', index:ri}],
      'is ' + a + ' <= ' + b + ' ? -> ' + r + ((a === b && r) ? '  (tie -> prefer LEFT, keeps the sort stable)' : ''));
    return r;
  }
  function take(side) {
    tick(); var A = arrOf(side); var idx = (side === 'left') ? li : ri; var e = A[idx];
    if (!e) throw new Error('take("' + side + '") on an empty run');
    if (side === 'left') li++; else ri++;
    out.push(e);
    snap('take', [{side:side, index:idx}, {side:'out', index:out.length-1}],
      'take ' + e.v + (e.tag ? '(' + e.tag + ')' : '') + ' from ' + side + ' -> output[' + (out.length-1) + ']');
    return e.v;
  }
  function note(t) { tick(); snap('note', [], String(t)); }
  onmessage = function (ev) {
    var d = ev.data;
    L = d.left; R = d.right; out = []; li = 0; ri = 0; frames = []; ops = 0; t0 = Date.now();
    var fn;
    try {
      fn = new Function('front','isEmpty','lessOrEqual','take','note',
        '"use strict";\n' + d.code + '\n;if (typeof merge === "function") { merge("left","right"); }');
    } catch (e1) {
      postMessage({ok:false, error:'Syntax error: ' + (e1 && e1.message ? e1.message : e1), frames:[]});
      return;
    }
    try {
      fn(front, isEmpty, lessOrEqual, take, note);
      snap('done', [], 'merge returned — output holds ' + out.length + ' value(s)');
      postMessage({ok:true, frames:frames});
    } catch (e2) {
      postMessage({ok:false, error:String((e2 && e2.message) || e2), frames:frames});
    }
  };
};

function uidRank(u) { return u.charAt(0) === 'L' ? (+u.slice(1)) : 10000 + (+u.slice(1)); }
function checkResult(out, total) {
  if (out.length < total) return { ok:false, why:'only ' + out.length + ' of ' + total + ' values were taken — the merge must drain both runs' };
  for (var q = 1; q < out.length; q++)
    if (out[q].v < out[q-1].v) return { ok:false, why:'output is not non-decreasing (' + out[q-1].v + ' before ' + out[q].v + ')' };
  var pairs = [];
  for (var a = 0; a < out.length; a++) for (var b = a+1; b < out.length; b++)
    if (out[a].v === out[b].v && uidRank(out[a].uid) > uidRank(out[b].uid)) pairs.push([a, b]);
  if (pairs.length) return { ok:false, pairs:pairs, why:"sorted, but UNSTABLE — a tie took the right run's 2 before the left run's 2 (use <=, not <)" };
  return { ok:true };
}

var currentWorker = null;
function trigger_runMerge() {
  pause();
  var code = document.getElementById('mergeImplementationCode').value;
  var parsed;
  try { parsed = parseRuns(document.getElementById('mergeImplementationInput').value); }
  catch (e) { setStatus('⚠ Runs: ' + e.message, '#c0392b'); return; }
  var m = findMerge(parsed.left, parsed.right);
  if (!m) {
    setStatus('⚠ no adjacent pair of runs in the tree matches that input — try 2,5 | 4,7 or 1,3 | 2,6 or 2,4,5,7 | 1,2,3,6', '#c0392b');
    return;
  }
  if (currentTier !== m.tier) setMergeLevel(m.tier); else clearReplay();
  activeMerge = m;
  var leftEls = m.left.els.map(function(e, q){ return {v:e.v, tag:e.tag, uid:'L'+q}; });
  var rightEls = m.right.els.map(function(e, q){ return {v:e.v, tag:e.tag, uid:'R'+q}; });
  var runBtn = document.getElementById('runBtn');
  runBtn.disabled = true;
  setStatus('running…', '#21618c');
  var url = URL.createObjectURL(new Blob(['(' + workerFn.toString() + ')()'], {type:'text/javascript'}));
  var w = new Worker(url);
  currentWorker = w;
  var settled = false;
  var killer = setTimeout(function () {
    if (settled) return; settled = true;
    try { w.terminate(); } catch (e) {}
    URL.revokeObjectURL(url);
    finishRun({ ok:false, error:'timed out after 2s — possible infinite loop', frames:[] });
  }, 2000);
  w.onmessage = function (ev) {
    if (settled) return; settled = true;
    clearTimeout(killer);
    try { w.terminate(); } catch (e) {}
    URL.revokeObjectURL(url);
    finishRun(ev.data);
  };
  w.onerror = function (ev) {
    if (settled) return; settled = true;
    clearTimeout(killer);
    URL.revokeObjectURL(url);
    finishRun({ ok:false, error:String(ev.message || 'worker error'), frames:[] });
  };
  w.postMessage({ code:code, left:leftEls, right:rightEls });
}
function finishRun(data) {
  document.getElementById('runBtn').disabled = false;
  frames = data.frames || [];
  if (!data.ok) {
    var st = frames.length ? frames[frames.length-1].state : {li:0, ri:0, out:[]};
    frames.push({kind:'error', indices:[], message:'⚠ ' + (data.error || 'unknown error'), state:st});
  }
  wrongPairs = [];
  if (!frames.length) { setStatus('⚠ ' + (data.error || 'no frames produced'), '#c0392b'); return; }
  if (!data.ok) {
    runVerdict = 'error';
    setStatus('⚠ error — see the last replay frame', '#c0392b');
  } else {
    var out = frames[frames.length-1].state.out;
    var chk = checkResult(out, activeMerge.left.els.length + activeMerge.right.els.length);
    if (chk.ok) { runVerdict = 'correct'; setStatus('✓ correct — sorted AND stable: ties took the LEFT run', '#1e8449'); }
    else { runVerdict = 'wrong'; wrongPairs = chk.pairs || []; setStatus('✗ ' + chk.why, '#c0392b'); }
  }
  frameIdx = 0;
  drawFrame(0);
}

/* ── replay drawing ─────────────────────────────────────────────── */
var KINDCOLOR = { compare:'#e67e22', take:'#1e8449', front:'#5dade2', isempty:'#85c1e9', note:'#888' };
function paintRun(node, ptr, color) {
  for (var q = 0; q < node.cells.length; q++) {
    var c = node.cells[q], el = node.els[q];
    if (q < ptr) {
      c.bg.fill('#f6f6f6'); c.text.fill('#b4b4b4');
      c.tag.opacity(traceOn && el.tag ? 0.35 : 0);
    } else {
      c.bg.fill('#e7e7e7'); c.text.fill('#111');
      c.tag.opacity(traceOn && el.tag ? 1 : 0);
    }
    if (q === ptr) {
      overlayG.rect(CW-10, RH-10).move(c.x+5, node.y+5).fill('none').stroke({color:color, width:3});
      overlayG.polygon((c.cx-7)+','+(node.y+6)+' '+(c.cx+7)+','+(node.y+6)+' '+c.cx+','+(node.y+17)).fill(color);
    }
  }
}
function drawFrame(idx) {
  if (!activeMerge || !frames.length) return;
  frameIdx = idx;
  var f = frames[idx];
  var P = activeMerge.parent, L = activeMerge.left, R = activeMerge.right;
  overlayG.clear();
  resetNodeDisplay(P); resetNodeDisplay(L); resetNodeDisplay(R);
  [P, L, R].forEach(function (nd) {
    overlayG.rect(nd.w+10, RH+10).move(nd.x-5, nd.y-5).fill('none')
      .stroke({color:'#2e86c1', width:2, opacity:0.55}).attr('stroke-dasharray','6,4');
  });
  var st = f.state, out = st.out;
  for (k = 0; k < P.cells.length; k++) {
    var pc = P.cells[k];
    if (k < out.length) {
      pc.text.text(String(out[k].v)).fill('#111').opacity(1);
      if (out[k].tag) { pc.tag.text(out[k].tag).fill(TAGC[out[k].tag]).opacity(traceOn ? 1 : 0); } else pc.tag.opacity(0);
    } else { pc.text.text(''); pc.tag.opacity(0); }
    if (k === out.length && f.kind !== 'done' && f.kind !== 'error') {
      overlayG.rect(CW-8, RH-8).move(pc.x+4, P.y+4).fill('none').stroke({color:'#7d6608', width:2}).attr('stroke-dasharray','4,3');
    }
  }
  paintRun(L, st.li, '#0b7fab');
  paintRun(R, st.ri, '#c25e10');
  var col = KINDCOLOR[f.kind] || '#888';
  (f.indices || []).forEach(function (ix) {
    var cell = null, ny = 0;
    if (ix.side === 'left' && L.cells[ix.index])  { cell = L.cells[ix.index];  ny = L.y; }
    if (ix.side === 'right' && R.cells[ix.index]) { cell = R.cells[ix.index];  ny = R.y; }
    if (ix.side === 'out' && P.cells[ix.index])   { cell = P.cells[ix.index];  ny = P.y; }
    if (cell) overlayG.rect(CW-6, RH-6).move(cell.x+3, ny+3).fill('none').stroke({color:col, width:3});
  });
  if (idx === frames.length-1) {
    if (runVerdict === 'correct') {
