    }
  }
  var cap = document.getElementById('replayCaption');
  cap.textContent = f.message;
  cap.style.color = f.kind === 'error' ? '#c0392b' : '#333';
  document.getElementById('frameCounter').textContent = (idx+1) + ' of ' + frames.length;
  var log = document.getElementById('replayLog');
  var lines = [];
  for (var q = 0; q <= idx; q++) lines.push((q+1) + '. ' + frames[q].message);
  log.value = lines.join('\n');
  log.scrollTop = log.scrollHeight;
}

