    if (!playing) return;
    frameIdx++; drawFrame(frameIdx); scheduleNext();
  }, 550 / speed);
}
function replayFirst() { if (!frames.length) return; pause(); drawFrame(0); }
function replayPrev()  { if (!frames.length) return; pause(); if (frameIdx > 0) drawFrame(frameIdx-1); }
function replayNext()  { if (!frames.length) return; pause(); if (frameIdx < frames.length-1) drawFrame(frameIdx+1); }
function replayPlayPause() {
  if (!frames.length) return;
  if (playing) { pause(); return; }
  if (frameIdx >= frames.length-1) frameIdx = -1;
  if (frameIdx < 0) { frameIdx = 0; drawFrame(0); }
  playing = true;
  document.getElementById('playBtn').textContent = '⏸';
  scheduleNext();
}
function setSpeed(v) { speed = v; }

